  align-items: flex-start;
  gap: 0.4rem;
  padding: 0.6rem 0.8rem;
  border-radius: 0.6rem;
  font-size: 0.78rem;
  line-height: 1.5;
  animation: slideIn 0.3s ease;
  direction: rtl;
  text-align: right;
  min-height: 40px;
}
